#define pi 3.14
vec3 getRandomColor(float t)
{
    return vec3( sin(t + iTime) , sin(t ) + .33 , sin(t + iTime)+ .66);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = (fragCoord * 2.  - iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.);
    float c;
    vec3 rcol;

      for(int i=0 ; i < 3 ; i++)
      {
            uv = fract(uv * 1.5) - .5;

            //vec3 col = vec3(uv , 0);

            float d = length(uv);

            rcol = getRandomColor(d);


            d = sin (d*8.- iTime*2.) / 8.; //to draw a signed circle of radius .5
            d = abs (d); //to change negative values to positive ,, inside the circle
            c = d;
            //  c = step ( .01 , d);
            c = smoothstep ( .0 , 0.05 , d );
            c = .3 / c;

            col += vec3(c);
       }

    col *= rcol;


    //contast speed
    col *= .35 * sin(iTime * .5) + .4 ;

    fragColor = vec4(col,1.0);
}
